CREATE POLICY salon_members_receive_salon_broadcasts ON realtime.messages FOR SELECT TO authenticated USING (extension='broadcast' AND CASE WHEN split_part(realtime.topic(),':',1)='salon' AND split_part(realtime.topic(),':',2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN public.can_access_salon(split_part(realtime.topic(),':',2)::uuid) ELSE false END); CREATE OR REPLACE FUNCTION public.handle_salon_message_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_event text; BEGIN IF NEW.propagation_disabled THEN RETURN NEW; END IF; IF TG_OP='INSERT' THEN v_event:='salon_message_sent'; ELSIF NEW.is_deleted AND NOT OLD.is_deleted THEN v_event:='salon_message_deleted'; ELSIF NEW.edited_at IS DISTINCT FROM OLD.edited_at THEN v_event:='salon_message_edited'; ELSE RETURN NEW; END IF; PERFORM realtime.send(jsonb_build_object('message_id',NEW.id,'salon_id',NEW.salon_id),v_event,'salon:'||NEW.salon_id::text,true); RETURN NEW; END; $$;